INSERT INTO `tb_products` VALUES (1,'TAR-ASU-407','Tarjeta de Video ASUS Dual GeForce RTX 4070 Super','Memoria de 12GB GDDR6X, diseño de 2.5 ranuras, tecnología de ventiladores Axial-tech y renderizado por IA con DLSS 3.',14499.00,10,1,'2026-09-22 10:47:42','2026-09-22 10:47:42'),(2,'PRO-AMD-78X','Procesador AMD Ryzen 7 7800X3D','8 núcleos y 16 hilos, reloj base de 4.2GHz (Turbo hasta 5.0GHz), 104MB de caché L2+L3 con tecnología 3D V-Cache, Socket AM5.',8299.00,25,1,'2026-09-22 10:47:42','2026-09-22 10:47:42'),(3,'SSD-SAM-990','SSD NVMe M.2 Samsung 990 PRO 2TB','Disco de estado sólido PCIe Gen 4.0 x4 con velocidades de lectura de hasta 7450 MB/s y escritura de hasta 6900 MB/s, ideal para PC y PS5.',3899.50,35,1,'2026-09-22 10:47:42','2026-09-22 10:47:42'),(4,'RAM-COR-32G','Memoria RAM Corsair Vengeance DDR5 32GB','Kit de 2x16GB a 6000MHz CL36, optimizado para Intel XMP 3.0 y AMD EXPO, disipador de aluminio de bajo perfil.',2450.00,50,1,'2026-09-22 10:47:42','2026-09-22 10:47:42'),(5,'FUEN-COR-RM8','Fuente de Poder Corsair RM850e 850W','Certificación 80 PLUS Gold, totalmente modular, compatible con ATX 3.0 y PCIe 5.0, condensadores de grado industrial a 105°C.',2799.00,20,1,'2026-09-22 10:47:42','2026-09-22 10:47:42'),(6,'DIS-WD-4TB','Disco Duro Externo WD My Passport 4TB','Disco duro portátil USB 3.2 Gen 1, protección mediante contraseña con cifrado de hardware AES de 256 bits, formato de 2.5 pulgadas compatible con PC y Mac.',2199.00,25,1,'2026-09-22 10:57:54','2026-09-22 10:57:54'),(7,'CAM-LOG-C920','Webcam Logitech C920 HD Pro','Cámara web Full HD 1080p a 30 fps, sonido estéreo con micrófonos dobles, corrección de luz automática HD y enfoque automático.',1499.50,18,1,'2026-09-22 10:57:54','2026-09-22 10:57:54'),(8,'SKU-0101-00001','Oster Batidora de Mano Compacta','Perfecto para quienes buscan comodidad, durabilidad y un excelente costo-beneficio. Categoría: Hogar y Cocina.',55.72,959,1,'2026-09-29 10:58:44','2026-09-29 10:58:44'),(9,'SKU-0000-00002','Samsung Cám